// The bundled exercise catalog: Resources/catalog.json, generated by scripts/ios/build-catalog.ts
// from prisma/seeds/exercise-definitions.json. Image files live in the app target
// (ios/App/ExerciseImages); the catalog only names them.

import Foundation

/// One row of catalog.json: everything the seed has, plus bundled image names.
struct CatalogRecord: Decodable, Sendable {
    let id: String
    let name: String
    let normalizedName: String
    let aliases: [String]
    let category: String?
    let equipment: [String]
    let primaryFAUs: [String]
    let secondaryFAUs: [String]
    let instructions: String?
    let force: String?
    let mechanic: String?
    let level: String?
    let images: [String]
}

enum BundledCatalog {
    struct Loaded: Sendable {
        let records: [CatalogRecord]
        let catalog: ExerciseCatalog
    }

    private static let cached: Result<Loaded, Error> = Result {
        guard let url = Bundle.module.url(forResource: "catalog", withExtension: "json") else {
            throw RipitCoreError.notFound("catalog.json")
        }
        let records = try JSONDecoder().decode([CatalogRecord].self, from: Data(contentsOf: url))
        let exercises = records.map {
            CatalogExercise(id: $0.id, name: $0.name, aliases: $0.aliases, category: $0.category,
                            equipment: $0.equipment, images: $0.images)
        }
        return Loaded(records: records, catalog: ExerciseCatalog(exercises: exercises))
    }

    static func load() throws -> Loaded { try cached.get() }
}
